window.KS = window.KS || {}; KS.bank = KS.bank || {};
KS.bank.scisoc = [
  // ===== Science: Patterns of Weather (sci-weather) =====
  { id: "wx-001", skill: "sci-weather", q: "Air moves from areas of ___ pressure to areas of ___ pressure.", choices: ["high; low", "low; high", "cold; warm", "wet; dry"], answer: 0, explain: "Wind blows from high pressure toward low pressure, like air rushing out of a balloon." },
  { id: "wx-002", skill: "sci-weather", q: "On a sunny afternoon at the beach, a cool wind blows from the ocean toward the land. What is this wind called?", choices: ["sea breeze", "land breeze", "jet stream", "trade wind"], answer: 0, explain: "In the daytime, land heats up faster than water. Warm air over the land rises, and cooler air from over the sea moves in to take its place." },
  { id: "wx-003", skill: "sci-weather", q: "When does a land breeze (wind blowing from the land out toward the sea) usually happen?", choices: ["During the day, when land heats up faster than water", "Only during hurricanes", "Only when the tide comes in", "At night, when land cools off faster than water"], answer: 3, explain: "At night the land cools faster than the water. Air over the warmer water rises, so cooler air from the land flows out to sea." },
  { id: "wx-004", skill: "sci-weather", q: "In a convection current in the air, warm air ___ and cool air ___.", choices: ["sinks; rises", "rises; sinks", "stays still; rises", "sinks; stays still"], answer: 1, explain: "Warm air is less dense, so it rises. Cooler, denser air sinks to take its place, making a loop called a convection current." },
  { id: "wx-005", skill: "sci-weather", q: "Why does warm air rise?", choices: ["It is less dense than the cooler air around it", "It is heavier than cool air", "It always holds more dust", "Gravity pulls warm air upward"], answer: 0, explain: "When air warms, its molecules spread apart, so it becomes less dense and floats up above cooler, denser air." },
  { id: "wx-006", skill: "sci-weather", q: "What is the main cause of wind?", choices: ["the moon's gravity", "earthquakes under the ocean", "Earth's magnetic field", "uneven heating of Earth's surface by the sun"], answer: 3, explain: "The sun heats some places more than others. That makes differences in air pressure, and air moves from high to low pressure as wind." },
  { id: "wx-007", skill: "sci-weather", q: "What is humidity?", choices: ["the amount of water vapor in the air", "the speed of the wind", "the weight of the air pressing down", "how fast ice melts"], answer: 0, explain: "Humidity measures how much water vapor (water in gas form) is in the air. High humidity makes the air feel sticky." },
  { id: "wx-008", skill: "sci-weather", q: "The temperature at which air becomes saturated and water vapor starts to condense into liquid water is called the ___.", choices: ["boiling point", "freezing point", "dew point", "melting point"], answer: 2, explain: "When air cools to its dew point, it can't hold all its water vapor, so tiny drops of liquid water form." },
  { id: "wx-009", skill: "sci-weather", q: "In the morning you see tiny water drops on the grass, but it did not rain. What happened?", choices: ["Water evaporated out of the grass overnight", "Groundwater rose up through the soil onto the leaves", "Sunlight turned the air into water", "The air cooled to its dew point and water vapor condensed"], answer: 3, explain: "At night the air near the ground cooled to its dew point, so water vapor condensed into liquid drops called dew." },
  { id: "wx-010", skill: "sci-weather", q: "What does a relative humidity of 100% mean?", choices: ["It is definitely raining", "The air is holding all the water vapor it can at that temperature", "The air has no water vapor at all", "The temperature is 100 degrees"], answer: 1, explain: "100% relative humidity means the air is saturated. It can't hold any more water vapor at that temperature, so clouds, fog, or dew can form." },
  { id: "wx-011", skill: "sci-weather", q: "How do clouds form?", choices: ["Water vapor cools and condenses on tiny particles like dust", "Water evaporates out of the clouds", "Air warms up and sinks toward the ground", "Sunlight bounces off the ocean"], answer: 0, explain: "As air rises it cools. The water vapor condenses into tiny droplets around bits of dust, salt, or smoke, and billions of droplets make a cloud." },
  { id: "wx-012", skill: "sci-weather", q: "Which clouds are puffy and white, look like cotton balls, and usually mean fair weather?", choices: ["stratus", "cirrus", "cumulus", "cumulonimbus"], answer: 2, explain: "Cumulus clouds are the puffy 'cotton ball' clouds you see on nice days." },
  { id: "wx-013", skill: "sci-weather", q: "Which clouds are thin, wispy, and feathery, and form high in the sky out of ice crystals?", choices: ["cirrus", "cumulus", "stratus", "cumulonimbus"], answer: 0, explain: "Cirrus clouds are so high and cold that they are made of ice crystals, which makes them look like thin feathers." },
  { id: "wx-014", skill: "sci-weather", q: "Which clouds form flat, gray layers that cover the whole sky and can bring drizzle?", choices: ["stratus", "cirrus", "cumulus", "cumulonimbus"], answer: 0, explain: "Stratus means 'layer.' Stratus clouds spread across the sky like a gray blanket." },
  { id: "wx-015", skill: "sci-weather", q: "Which clouds are very tall and dark and bring thunderstorms, lightning, and sometimes hail?", choices: ["stratus", "cirrus", "cumulus", "cumulonimbus"], answer: 3, explain: "Cumulonimbus clouds are giant thunderstorm clouds. 'Nimbus' means rain." },
  { id: "wx-016", skill: "sci-weather", q: "You see tall, dark clouds building in the west, and the air suddenly feels cool and windy. What is most likely coming?", choices: ["several days of calm, clear weather", "a slow, gentle warm-up", "a thunderstorm", "a heat wave"], answer: 2, explain: "Tall, dark cumulonimbus clouds and a sudden cool, gusty wind are signs of a thunderstorm, often along a cold front." },
  { id: "wx-017", skill: "sci-weather", q: "Which of these is NOT a form of precipitation?", choices: ["fog", "rain", "sleet", "hail"], answer: 0, explain: "Precipitation is water that falls from clouds to the ground. Fog is a cloud near the ground; it doesn't fall." },
  { id: "wx-018", skill: "sci-weather", q: "Hail most often forms in which kind of cloud?", choices: ["cirrus clouds high in the sky", "cumulonimbus clouds with strong updrafts", "thin stratus clouds", "fog near the ground"], answer: 1, explain: "In a cumulonimbus cloud, strong updrafts carry ice up and down again and again, adding layers until the hailstones are heavy enough to fall." },
  { id: "wx-019", skill: "sci-weather", q: "What is sleet?", choices: ["rain that freezes into ice pellets as it falls through cold air near the ground", "snow that melts completely before it lands", "a type of thin cloud", "fog that stays all day"], answer: 0, explain: "Sleet starts as rain or melted snow, then freezes into little ice pellets while falling through a cold layer of air." },
  { id: "wx-020", skill: "sci-weather", q: "A huge body of air that has about the same temperature and humidity throughout is called a(n) ___.", choices: ["air mass", "front", "jet stream", "barometer"], answer: 0, explain: "An air mass takes on the temperature and moisture of the place where it forms, like over an ocean or over cold land." },
  { id: "wx-021", skill: "sci-weather", q: "An air mass that forms over the warm Gulf of Mexico would most likely be ___.", choices: ["cold and dry", "cold and moist", "warm and moist", "warm and dry"], answer: 2, explain: "Air over warm ocean water picks up heat and lots of water vapor, so it becomes warm and humid." },
  { id: "wx-022", skill: "sci-weather", q: "An air mass that forms over northern Canada in winter would most likely be ___.", choices: ["cold and dry", "warm and moist", "warm and dry", "cold and moist"], answer: 0, explain: "Air over cold land gets cold, and because it formed over land instead of water, it is dry." },
  { id: "wx-023", skill: "sci-weather", q: "The boundary where two different air masses meet is called a ___.", choices: ["barometer", "jet stream", "dew point", "front"], answer: 3, explain: "A front is the 'battle line' between two air masses. Weather often changes when a front passes." },
  { id: "wx-024", skill: "sci-weather", q: "A cold front pushes under warm air and forces it up quickly. What weather does a cold front usually bring?", choices: ["days of light drizzle and warmer weather", "thunderstorms or heavy rain, then cooler, clearer weather", "no change in the weather", "a week of thick fog"], answer: 1, explain: "Warm air shoved upward fast builds tall storm clouds. After the front passes, cooler, drier air moves in." },
  { id: "wx-025", skill: "sci-weather", q: "At a warm front, warm air slowly slides up over cold air. What weather does a warm front usually bring?", choices: ["steady light rain or drizzle for a long time, then warmer weather", "sudden violent thunderstorms, then colder air", "a tornado every time", "clear, dry skies only"], answer: 0, explain: "Warm air rises gently over the cold air, making wide layers of clouds and long, steady rain. Then it gets warmer." },
  { id: "wx-026", skill: "sci-weather", q: "A front stops moving and stays over the same area. What weather might this stationary front bring?", choices: ["one quick thunderstorm, then clear skies", "dry, sunny weather for weeks", "several days of cloudy, wet weather in the same place", "a hurricane"], answer: 2, explain: "Because a stationary front stays put, the same clouds and rain can sit over one area for days." },
  { id: "wx-027", skill: "sci-weather", q: "What is an occluded front?", choices: ["a warm front that stops moving", "two warm air masses meeting", "an air mass over the ocean", "a fast cold front that catches up to a warm front and lifts the warm air off the ground"], answer: 3, explain: "Cold fronts move faster than warm fronts. When one catches up, the warm air gets pushed up and cut off from the ground." },
  { id: "wx-028", skill: "sci-weather", q: "On a weather map, a blue line with triangles shows a ___.", choices: ["cold front", "warm front", "stationary front", "occluded front"], answer: 0, explain: "Cold fronts are drawn in blue (for cold) with triangles pointing the way the front is moving." },
  { id: "wx-029", skill: "sci-weather", q: "On a weather map, a red line with half-circles shows a ___.", choices: ["cold front", "occluded front", "warm front", "stationary front"], answer: 2, explain: "Warm fronts are drawn in red (for warm) with half-circles pointing the way the front is moving." },
  { id: "wx-030", skill: "sci-weather", q: "On a weather map, a purple line with triangles and half-circles on the SAME side shows a(n) ___.", choices: ["occluded front", "stationary front", "cold front", "warm front"], answer: 0, explain: "An occluded front is a mix of a cold and warm front, so it is purple with both symbols pointing the same way." },
  { id: "wx-031", skill: "sci-weather", q: "On a weather map, a line with red half-circles on one side and blue triangles on the other side shows a ___.", choices: ["warm front", "cold front", "occluded front", "stationary front"], answer: 3, explain: "A stationary front has both symbols pointing in opposite directions because neither air mass is winning, so the front isn't moving." },
  { id: "wx-032", skill: "sci-weather", q: "A big blue 'H' on a weather map marks a high-pressure system. What weather does it usually bring?", choices: ["stormy, cloudy weather", "clear, fair weather", "hurricane-force winds", "heavy snowstorms"], answer: 1, explain: "In a high-pressure system, air sinks and warms, which keeps clouds from forming, so skies are usually clear." },
  { id: "wx-033", skill: "sci-weather", q: "A red 'L' on a weather map marks a low-pressure system. What weather does it usually bring?", choices: ["clear, sunny skies", "very dry, calm air", "cloudy, wet, or stormy weather", "no wind at all"], answer: 2, explain: "In a low-pressure system, air rises and cools, so water vapor condenses into clouds and rain or storms." },
  { id: "wx-034", skill: "sci-weather", q: "What happens to the air in the center of a low-pressure system?", choices: ["It rises, cools, and forms clouds", "It sinks and warms, clearing the clouds", "It stays perfectly still", "It turns into ice"], answer: 0, explain: "Air flows in toward the low and rises. Rising air cools, and cooling air makes clouds." },
  { id: "wx-035", skill: "sci-weather", q: "Which instrument measures air pressure?", choices: ["anemometer", "hygrometer", "rain gauge", "barometer"], answer: 3, explain: "A barometer measures air pressure. Falling pressure often means stormy weather is on the way." },
  { id: "wx-036", skill: "sci-weather", q: "Which instrument measures wind speed?", choices: ["anemometer", "barometer", "wind vane", "thermometer"], answer: 0, explain: "An anemometer has spinning cups. The faster the wind blows, the faster the cups spin." },
  { id: "wx-037", skill: "sci-weather", q: "Which instrument measures humidity?", choices: ["thermometer", "barometer", "hygrometer (or psychrometer)", "rain gauge"], answer: 2, explain: "A hygrometer or psychrometer measures how much water vapor is in the air." },
  { id: "wx-038", skill: "sci-weather", q: "Which instrument shows the direction the wind is blowing FROM?", choices: ["wind vane", "anemometer", "barometer", "hygrometer"], answer: 0, explain: "A wind vane points into the wind, showing the direction the wind is coming from." },
  { id: "wx-039", skill: "sci-weather", q: "What does a rain gauge measure?", choices: ["how hot the air is", "how much rain has fallen", "how fast the wind blows", "the air pressure"], answer: 1, explain: "A rain gauge is a container that collects rain so you can measure how much fell." },
  { id: "wx-040", skill: "sci-weather", q: "Your barometer shows the air pressure is dropping quickly. What weather is most likely coming?", choices: ["clear, dry weather", "no change in the weather", "a cloudless sky for days", "stormy weather"], answer: 3, explain: "Fast-falling pressure means a low-pressure system is moving in, and lows bring clouds and storms." },
  { id: "wx-041", skill: "sci-weather", q: "A meteorologist wants to know how hot or cold the air is. Which tool should she use?", choices: ["thermometer", "barometer", "anemometer", "rain gauge"], answer: 0, explain: "A thermometer measures temperature." },
  { id: "wx-042", skill: "sci-weather", q: "As you climb higher up a tall mountain, the air pressure ___.", choices: ["decreases", "increases", "stays exactly the same", "doubles every few steps"], answer: 0, explain: "Air pressure gets lower the higher you go, because there is less air above you pressing down." },
  { id: "wx-043", skill: "sci-weather", q: "Why is air pressure lower at the top of a mountain than at sea level?", choices: ["The air is hotter at the top", "Gravity is stronger at the top", "Clouds push the air down", "There is less air above pressing down"], answer: 3, explain: "Air pressure is the weight of the air above you. Higher up, there is less air on top, so the pressure is lower." },
  { id: "wx-044", skill: "sci-weather", q: "What causes thunder?", choices: ["clouds bumping into each other", "lightning heating the air so fast that it expands with a boom", "rain hitting the ground", "wind blowing through trees"], answer: 1, explain: "Lightning heats the air to extremely high temperatures in an instant. The air expands so fast it makes a loud boom." },
  { id: "wx-045", skill: "sci-weather", q: "During a storm, why do you see the lightning before you hear the thunder?", choices: ["Light travels much faster than sound", "Thunder happens first, then lightning", "Sound travels faster than light", "Your eyes are closer to the cloud than your ears"], answer: 0, explain: "Light reaches you almost instantly, but sound travels much more slowly, so the thunder arrives later." },
  { id: "wx-046", skill: "sci-weather", q: "What is a tornado?", choices: ["a large ocean storm hundreds of miles wide", "a gentle breeze from the sea", "a rapidly spinning column of air reaching from a thunderstorm down to the ground", "a long period with no rain"], answer: 2, explain: "Tornadoes are small but extremely powerful spinning columns of air that come down from strong thunderstorms." },
  { id: "wx-047", skill: "sci-weather", q: "Where do hurricanes form?", choices: ["over cold polar land", "over deserts", "over frozen lakes", "over warm ocean water"], answer: 3, explain: "Hurricanes get their energy from warm, moist air rising off warm ocean water." },
  { id: "wx-048", skill: "sci-weather", q: "Why does a hurricane usually weaken after it moves over land?", choices: ["It loses its supply of warm, moist ocean air", "Land makes the winds spin faster", "Mountains freeze it", "Land has higher tides"], answer: 0, explain: "Warm ocean water is a hurricane's fuel. Over land it runs out of fuel and slowly weakens." },
  { id: "wx-049", skill: "sci-weather", q: "What is the 'eye' of a hurricane?", choices: ["the calm center of the storm", "the part with the very strongest winds", "the outer edge where the rain bands begin", "the cold front behind the storm"], answer: 0, explain: "The eye is the calm, often clear center. The strongest winds are in the eyewall right around it." },
  { id: "wx-050", skill: "sci-weather", q: "Global winds that blow in steady patterns around Earth are caused by ___.", choices: ["the moon's gravity", "ocean tides", "uneven heating of Earth's surface and Earth's rotation", "earthquakes"], answer: 2, explain: "The equator gets more direct sunlight than the poles. That uneven heating moves air, and Earth's spin curves it into wind belts." },
  { id: "wx-051", skill: "sci-weather", q: "What is the jet stream?", choices: ["a fast band of wind high in the atmosphere that steers weather systems", "a warm ocean current", "a kind of sea breeze", "a type of cloud"], answer: 0, explain: "The jet stream is a river of fast wind high above us. It helps push storms and fronts across the country." },
  { id: "wx-052", skill: "sci-weather", q: "In most of the United States, weather systems generally move from ___.", choices: ["east to west", "west to east", "south to north", "north to south"], answer: 1, explain: "The prevailing westerlies and the jet stream push weather from west to east, so check the weather to your west to see what's coming." },
  { id: "wx-053", skill: "sci-weather", q: "What is the Coriolis effect?", choices: ["the moon pulling on the oceans", "warm air rising", "clouds forming from water vapor", "Earth's rotation making winds curve instead of blowing in straight lines"], answer: 3, explain: "Because Earth spins, winds and ocean currents curve. In the Northern Hemisphere they curve to the right." },
  { id: "wx-054", skill: "sci-weather", q: "The global winds that blow across most of the United States are called the ___.", choices: ["prevailing westerlies", "trade winds", "polar easterlies", "sea breezes"], answer: 0, explain: "The prevailing westerlies blow from west to east over the middle latitudes, where the U.S. is." },
  { id: "wx-055", skill: "sci-weather", q: "What is the difference between weather and climate?", choices: ["Weather is short-term conditions; climate is the long-term average pattern", "Weather is the long-term pattern; climate is short-term conditions", "Weather is only temperature; climate is only rainfall", "There is no difference"], answer: 0, explain: "Weather is what's happening outside today. Climate is the usual weather of a place averaged over many years." },
  { id: "wx-056", skill: "sci-weather", q: "Which statement describes CLIMATE?", choices: ["It is raining in Fairfax right now", "There will be a thunderstorm this afternoon", "Northern Virginia usually has hot, humid summers and cold winters", "The wind today is blowing at 10 miles per hour"], answer: 2, explain: "Climate describes the usual pattern over many years. The other choices describe weather at one moment." },
  { id: "wx-057", skill: "sci-weather", q: "In which layer of the atmosphere does almost all of Earth's weather happen?", choices: ["stratosphere", "mesosphere", "thermosphere", "troposphere"], answer: 3, explain: "The troposphere is the lowest layer, where we live. It holds most of the air's water vapor, so clouds and storms form there." },
  { id: "wx-058", skill: "sci-weather", q: "Monday's forecast says: High 72°F, Low 50°F, 80% chance of rain. What should you bring to school?", choices: ["a winter coat and snow boots", "an umbrella or raincoat", "nothing extra, rain is impossible", "only sunscreen"], answer: 1, explain: "An 80% chance of rain means rain is very likely, and 72°F isn't cold enough for a winter coat." },
  { id: "wx-059", skill: "sci-weather", q: "Forecast: Tuesday, thunderstorms (90% rain). Wednesday, sunny (10% rain). Thursday, cloudy (60% rain). Friday, snow showers. Which day is best for an outdoor picnic?", choices: ["Wednesday", "Tuesday", "Thursday", "Friday"], answer: 0, explain: "Wednesday is sunny with only a 10% chance of rain, the lowest chance of the four days." },
  { id: "wx-060", skill: "sci-weather", q: "On a weather station symbol, what does a circle that is completely filled in mean?", choices: ["clear skies", "it is snowing", "the sky is completely covered by clouds (overcast)", "high pressure"], answer: 2, explain: "The circle shows cloud cover: empty means clear and completely filled means overcast." },

  // ===== Science: Astronomy (review) (sci-astro) =====
  { id: "astro-001", skill: "sci-astro", q: "Which list shows the planets in order from the sun outward?", choices: ["Mercury, Venus, Earth, Mars, Saturn, Jupiter, Uranus, Neptune", "Venus, Mercury, Earth, Mars, Jupiter, Saturn, Neptune, Uranus", "Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune", "Mercury, Earth, Venus, Mars, Jupiter, Saturn, Uranus, Neptune"], answer: 2, explain: "A memory trick: 'My Very Educated Mother Just Served Us Nachos' = Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune." },
  { id: "astro-002", skill: "sci-astro", q: "Which planet is closest to the sun?", choices: ["Venus", "Mercury", "Mars", "Earth"], answer: 1, explain: "Mercury is the first planet from the sun." },
  { id: "astro-003", skill: "sci-astro", q: "Which planet is farthest from the sun?", choices: ["Pluto", "Uranus", "Neptune", "Saturn"], answer: 2, explain: "Neptune is the eighth and farthest planet. Pluto is now classified as a dwarf planet." },
  { id: "astro-004", skill: "sci-astro", q: "Which is the largest planet in our solar system?", choices: ["Jupiter", "Saturn", "Neptune", "Uranus"], answer: 0, explain: "Jupiter is the biggest planet, so big that more than 1,000 Earths could fit inside it." },
  { id: "astro-005", skill: "sci-astro", q: "Which four planets are the terrestrial (rocky) planets?", choices: ["Jupiter, Saturn, Uranus, Neptune", "Earth, Jupiter, Mars, Saturn", "Mercury, Mars, Uranus, Neptune", "Mercury, Venus, Earth, Mars"], answer: 3, explain: "The four inner planets, closest to the sun, are small and rocky with solid surfaces." },
  { id: "astro-006", skill: "sci-astro", q: "Which describes the terrestrial planets?", choices: ["small and rocky, with solid surfaces", "huge and made mostly of gas", "surrounded by large ring systems", "located beyond the asteroid belt"], answer: 0, explain: "Terrestrial means 'Earth-like.' Mercury, Venus, Earth, and Mars are small, rocky, and close to the sun." },
  { id: "astro-007", skill: "sci-astro", q: "What separates the inner (terrestrial) planets from the outer (giant) planets?", choices: ["the Kuiper belt", "Saturn's rings", "the asteroid belt", "the moon"], answer: 2, explain: "The asteroid belt lies between Mars and Jupiter, dividing the rocky inner planets from the giant outer planets." },
  { id: "astro-008", skill: "sci-astro", q: "Which describes the gas giants Jupiter and Saturn?", choices: ["rocky surfaces you could stand on", "very few or no moons", "orbits closer to the sun than Earth's", "thick gas atmospheres, many moons, and rings"], answer: 3, explain: "Gas giants are made mostly of hydrogen and helium, have no solid surface to stand on, and have many moons and rings." },
  { id: "astro-009", skill: "sci-astro", q: "Uranus and Neptune contain lots of icy materials, so they are often called ___.", choices: ["ice giants", "terrestrial planets", "dwarf planets", "asteroids"], answer: 0, explain: "Uranus and Neptune are giant outer planets with lots of ice-forming materials, so scientists call them ice giants." },
  { id: "astro-010", skill: "sci-astro", q: "A planet is very large, has rings, is made mostly of hydrogen and helium, and orbits beyond the asteroid belt. What type of planet is it?", choices: ["terrestrial planet", "dwarf planet", "gas giant", "moon"], answer: 2, explain: "Large size, rings, mostly gas, and a far-out orbit are all clues for a gas giant." },
  { id: "astro-011", skill: "sci-astro", q: "What is the sun?", choices: ["a planet", "a comet", "a galaxy", "a star"], answer: 3, explain: "The sun is a star, a giant ball of hot gas that makes its own light and heat." },
  { id: "astro-012", skill: "sci-astro", q: "The sun is a medium-sized star. Why does it look so much bigger and brighter than the stars we see at night?", choices: ["It is much closer to Earth than any other star", "It is the biggest star in the universe", "It is the only star that gives off light", "Other stars are not hot"], answer: 0, explain: "The sun is about 150 million km away, but the next nearest star is far, far farther. Closer things look bigger and brighter." },
  { id: "astro-013", skill: "sci-astro", q: "How does the sun make its energy?", choices: ["by burning coal", "by nuclear fusion, joining hydrogen into helium", "by reflecting light from the planets", "by collecting lightning"], answer: 1, explain: "Deep in the sun's core, hydrogen atoms are squeezed together to make helium. This nuclear fusion releases huge amounts of energy." },
  { id: "astro-014", skill: "sci-astro", q: "What keeps the planets in their orbits around the sun?", choices: ["Earth's magnetism", "wind in space", "the moon's light", "the sun's gravity"], answer: 3, explain: "The sun's gravity pulls on each planet, keeping it moving in a path around the sun." },
  { id: "astro-015", skill: "sci-astro", q: "The curved path an object follows as it revolves around another object is called its ___.", choices: ["orbit", "rotation", "axis", "eclipse"], answer: 0, explain: "An orbit is the path a planet or moon follows around another object." },
  { id: "astro-016", skill: "sci-astro", q: "Why don't the planets fly off into space or fall into the sun?", choices: ["There is no gravity in space", "They are attached to the sun by invisible strings", "The sun pushes them away", "The sun's gravity pulls on them while their forward motion keeps them moving around it"], answer: 3, explain: "Gravity pulls each planet inward while its speed carries it forward. Together they keep it circling the sun." },
  { id: "astro-017", skill: "sci-astro", q: "Which statement about gravity is true?", choices: ["Objects with more mass have a stronger pull of gravity", "There is no gravity in space", "Gravity gets stronger as objects move farther apart", "Only Earth has gravity"], answer: 0, explain: "The more mass an object has, the stronger its gravity. Gravity gets weaker as objects get farther apart." },
  { id: "astro-018", skill: "sci-astro", q: "What causes day and night on Earth?", choices: ["Earth rotating (spinning) on its axis", "Earth revolving around the sun", "the moon blocking the sun", "the sun moving around Earth"], answer: 0, explain: "As Earth spins, your side faces the sun (day) and then turns away from it (night)." },
  { id: "astro-019", skill: "sci-astro", q: "About how long does it take Earth to rotate once on its axis?", choices: ["about 1 hour", "about 365 days", "about 24 hours", "about 29.5 days"], answer: 2, explain: "One full spin of Earth takes about 24 hours, which is one day." },
  { id: "astro-020", skill: "sci-astro", q: "One year is the time it takes for ___.", choices: ["Earth to rotate once on its axis", "Earth to revolve once around the sun", "the moon to orbit Earth once", "the sun to orbit Earth"], answer: 1, explain: "Earth takes about 365 days (one year) to revolve all the way around the sun." },
  { id: "astro-021", skill: "sci-astro", q: "What causes Earth's seasons?", choices: ["Earth gets closer to the sun in summer and farther away in winter", "The sun burns hotter in summer", "The moon's position", "The tilt of Earth's axis as Earth revolves around the sun"], answer: 3, explain: "Seasons come from Earth's tilt, not its distance. In fact, Earth is closest to the sun in early January, during our winter." },
  { id: "astro-022", skill: "sci-astro", q: "When it is summer in the Northern Hemisphere, ___.", choices: ["Earth is at its closest point to the sun", "the Southern Hemisphere is tilted toward the sun", "the Northern Hemisphere is tilted toward the sun", "Earth stops tilting"], answer: 2, explain: "In June, the northern half of Earth tilts toward the sun, so it gets more direct sunlight and longer days." },
  { id: "astro-023", skill: "sci-astro", q: "Why are summer days warmer than winter days?", choices: ["Sunlight hits more directly and the days are longer", "Earth is closer to the sun in summer", "The sun gives off more heat in summer", "There are more clouds in summer"], answer: 0, explain: "When your hemisphere tilts toward the sun, sunlight is more direct and lasts more hours each day, so it heats the ground more." },
  { id: "astro-024", skill: "sci-astro", q: "It is July and summer in Virginia. What season is it in Australia, in the Southern Hemisphere?", choices: ["winter", "summer", "spring", "fall"], answer: 0, explain: "When the Northern Hemisphere tilts toward the sun, the Southern Hemisphere tilts away, so it is winter there." },
  { id: "astro-025", skill: "sci-astro", q: "What causes the phases of the moon?", choices: ["Earth's shadow falling on the moon", "Clouds covering part of the moon", "The moon making its own light", "We see different amounts of the moon's sunlit half as it orbits Earth"], answer: 3, explain: "The sun always lights half the moon. As the moon orbits Earth, we see more or less of that lit half. Earth's shadow causes eclipses, not phases." },
  { id: "astro-026", skill: "sci-astro", q: "Why does the moon shine in the night sky?", choices: ["It makes its own light like a star", "It reflects light from the sun", "It has glowing volcanoes", "It is made of glowing ice"], answer: 1, explain: "The moon doesn't make light. It reflects sunlight, like a mirror." },
  { id: "astro-027", skill: "sci-astro", q: "During a full moon, where is the moon?", choices: ["on the opposite side of Earth from the sun", "between Earth and the sun", "behind the sun", "at a right angle to the sun and Earth"], answer: 0, explain: "At full moon, Earth is between the sun and moon, so we see the moon's whole sunlit side." },
  { id: "astro-028", skill: "sci-astro", q: "Why can't we see the moon during a new moon?", choices: ["Earth's shadow completely covers it", "It moves behind the sun", "Its sunlit side faces away from Earth", "It stops reflecting light"], answer: 2, explain: "At new moon, the moon is between Earth and the sun, so the lit side faces away from us and we see the dark side." },
  { id: "astro-029", skill: "sci-astro", q: "About how long does it take the moon to go through all of its phases, from one new moon to the next?", choices: ["about 1 day", "about 1 week", "about 29.5 days (about a month)", "about 365 days"], answer: 2, explain: "The full cycle of moon phases takes about 29.5 days, which is where the idea of a 'month' comes from." },
  { id: "astro-030", skill: "sci-astro", q: "Right after a new moon, the lit part of the moon we see gets bigger each night. We say the moon is ___.", choices: ["waning", "waxing", "eclipsed", "rotating backward"], answer: 1, explain: "Waxing means growing. After a full moon, the lit part shrinks, which is called waning." },
  { id: "astro-031", skill: "sci-astro", q: "What happens during a solar eclipse?", choices: ["The moon passes between the sun and Earth, blocking sunlight", "Earth passes between the sun and the moon", "The moon moves into Earth's shadow", "The sun stops shining for a day"], answer: 0, explain: "In a solar eclipse, the moon blocks the sun from our view, and the moon's shadow falls on part of Earth." },
  { id: "astro-032", skill: "sci-astro", q: "What happens during a lunar eclipse?", choices: ["The moon passes between the sun and Earth", "The sun passes between Earth and the moon", "Earth passes between the sun and the moon, and Earth's shadow falls on the moon", "The moon spins so its dark side faces us"], answer: 2, explain: "In a lunar eclipse, Earth blocks sunlight from reaching the moon, so the moon darkens and often looks reddish." },
  { id: "astro-033", skill: "sci-astro", q: "What mainly causes ocean tides?", choices: ["the moon's gravity pulling on Earth's oceans", "wind blowing across the ocean", "earthquakes", "fish swimming"], answer: 0, explain: "The moon's gravity pulls on Earth's water, making it bulge. As Earth rotates, coasts move through these bulges (high tides). Wind makes waves, not tides." },
  { id: "astro-034", skill: "sci-astro", q: "What is an asteroid?", choices: ["a ball of ice and dust with a glowing tail", "a streak of light in the night sky", "a small star", "a rocky object orbiting the sun, many of them between Mars and Jupiter"], answer: 3, explain: "Asteroids are chunks of rock and metal. Most orbit the sun in the asteroid belt between Mars and Jupiter." },
  { id: "astro-035", skill: "sci-astro", q: "What is a comet?", choices: ["a rocky object in the asteroid belt", "a ball of ice, dust, and rock that forms a glowing tail when it gets near the sun", "a streak of light from a rock burning up in the air", "a moon of Jupiter"], answer: 1, explain: "Comets are like 'dirty snowballs.' The sun's heat turns some ice to gas, forming a glowing tail that points away from the sun." },
  { id: "astro-036", skill: "sci-astro", q: "A space rock that survives the trip through Earth's atmosphere and lands on the ground is called a ___.", choices: ["meteor", "meteoroid", "meteorite", "comet"], answer: 2, explain: "A meteoroid is the rock in space, a meteor is the streak of light as it burns up, and a meteorite is a piece that reaches the ground." },
  { id: "astro-037", skill: "sci-astro", q: "Which statement best describes the scale of the solar system?", choices: ["The planets are packed close together", "The sun is about the same size as Earth", "The planets are tiny compared to the huge distances between them", "Neptune is about as far from the sun as Mars is"], answer: 2, explain: "The solar system is mostly empty space. Even the giant planets are tiny dots compared to the distances between them." },
  { id: "astro-038", skill: "sci-astro", q: "Ptolemy's geocentric model placed ___ at the center of the universe.", choices: ["Earth", "the sun", "the moon", "Jupiter"], answer: 0, explain: "Geo means 'Earth.' Ptolemy, an ancient astronomer, thought the sun, moon, and planets all circled Earth." },
  { id: "astro-039", skill: "sci-astro", q: "Who proposed the heliocentric model, with the sun at the center and Earth orbiting it?", choices: ["Copernicus", "Ptolemy", "Aristotle", "Columbus"], answer: 0, explain: "Helio means 'sun.' Nicolaus Copernicus proposed that Earth and the other planets revolve around the sun." },
  { id: "astro-040", skill: "sci-astro", q: "Galileo used a telescope and saw moons orbiting Jupiter. Why did this support the heliocentric model?", choices: ["It proved Earth was flat", "It showed the sun orbits Earth", "It proved Jupiter is a star", "It showed that not everything in the sky orbits Earth"], answer: 3, explain: "If moons circle Jupiter, then Earth is not the center of everything. This helped support Copernicus's idea." },

  // ===== Science: H2O (sci-water) =====
  { id: "h2o-001", skill: "sci-water", q: "A water molecule is called 'polar' because ___.", choices: ["it is found mostly at the North and South Poles", "it has a slightly positive end and a slightly negative end", "it is made of two oxygen atoms and one hydrogen atom", "it is always frozen"], answer: 1, explain: "The oxygen end of a water molecule is slightly negative and the hydrogen ends are slightly positive, like a tiny magnet with two sides." },
  { id: "h2o-002", skill: "sci-water", q: "A water molecule (H2O) is made of ___.", choices: ["one hydrogen atom and two oxygen atoms", "two hydrogen atoms and two oxygen atoms", "two hydrogen atoms and one oxygen atom", "one hydrogen atom and one oxygen atom"], answer: 2, explain: "H2O means 2 hydrogen (H) atoms and 1 oxygen (O) atom." },
  { id: "h2o-003", skill: "sci-water", q: "You can fit many drops of water on a penny before it spills, because water molecules stick to EACH OTHER. This property is called ___.", choices: ["cohesion", "adhesion", "evaporation", "condensation"], answer: 0, explain: "Cohesion is water sticking to itself. The molecules hold together so the water forms a dome on the penny." },
  { id: "h2o-004", skill: "sci-water", q: "Water droplets cling to the side of a glass. Water sticking to a DIFFERENT material is called ___.", choices: ["adhesion", "cohesion", "precipitation", "density"], answer: 0, explain: "Adhesion is water sticking to other things. (A trick: Adhesion = Attached to another thing; Cohesion = Clinging to its own kind.)" },
  { id: "h2o-005", skill: "sci-water", q: "A water strider insect can walk on the surface of a pond. Which property of water makes this possible?", choices: ["adhesion", "high specific heat", "evaporation", "cohesion (surface tension)"], answer: 3, explain: "Water molecules at the surface cling tightly to each other, making a 'skin' called surface tension that can hold up a light insect." },
  { id: "h2o-006", skill: "sci-water", q: "At noon on a summer day, the sand at the beach feels hot but the ocean feels cool. Why?", choices: ["Water is always colder than sand", "The ocean reflects all of the sunlight", "The sand is wet", "Water has a high specific heat, so it heats up more slowly than sand"], answer: 3, explain: "Water has a high specific heat, which means it takes a lot of energy to warm up. Sand warms up much faster." },
  { id: "h2o-007", skill: "sci-water", q: "Water is called the 'universal solvent' because ___.", choices: ["it is found in every part of the universe", "it dissolves more substances than any other common liquid", "it can easily dissolve oil", "it never evaporates"], answer: 1, explain: "Because water molecules are polar, they can pull apart and dissolve many substances, like salt and sugar. Oil, though, does not dissolve in water." },
  { id: "h2o-008", skill: "sci-water", q: "Why does ice float on liquid water?", choices: ["Ice is denser than liquid water", "Ice is a different substance than water", "Cold things always float", "Ice is less dense than liquid water"], answer: 3, explain: "When water freezes, its molecules lock into an open pattern that takes up more space, so ice is less dense and floats." },
  { id: "h2o-009", skill: "sci-water", q: "Why is it important for fish that ice floats?", choices: ["Ice forms a layer on top that helps keep the water below from freezing", "Fish eat the ice", "Floating ice makes the lake warmer in summer", "Floating ice adds salt to the lake"], answer: 0, explain: "The ice on top acts like a lid that keeps heat in, so the water underneath stays liquid and fish can survive the winter." },
  { id: "h2o-010", skill: "sci-water", q: "In the water cycle, evaporation is when ___.", choices: ["water vapor cools into tiny droplets", "water falls from clouds", "liquid water is heated and changes into water vapor", "water soaks into the ground"], answer: 2, explain: "The sun's energy heats water in oceans, lakes, and puddles, turning it into an invisible gas called water vapor." },
  { id: "h2o-011", skill: "sci-water", q: "Water vapor high in the sky cools and changes back into tiny liquid droplets, forming clouds. This step is called ___.", choices: ["evaporation", "precipitation", "condensation", "runoff"], answer: 2, explain: "Condensation is gas changing to liquid, the same thing that makes drops form on a cold glass." },
  { id: "h2o-012", skill: "sci-water", q: "Rain, snow, sleet, and hail falling from clouds are all part of which step of the water cycle?", choices: ["evaporation", "condensation", "infiltration", "precipitation"], answer: 3, explain: "Precipitation is any water that falls from clouds to Earth's surface." },
  { id: "h2o-013", skill: "sci-water", q: "Plants release water vapor into the air through tiny openings in their leaves. This is called ___.", choices: ["transpiration", "precipitation", "runoff", "infiltration"], answer: 0, explain: "Transpiration is like plants 'breathing out' water vapor. It adds lots of water to the air." },
  { id: "h2o-014", skill: "sci-water", q: "What provides the energy that drives the water cycle?", choices: ["the sun", "the moon's gravity", "heat from Earth's core", "ocean tides"], answer: 0, explain: "The sun's energy evaporates water. Gravity then pulls precipitation down and makes water flow downhill." },
  { id: "h2o-015", skill: "sci-water", q: "Where is most of Earth's water found?", choices: ["in rivers and lakes", "in glaciers and ice caps", "in the oceans", "in the clouds"], answer: 2, explain: "About 97% of Earth's water is salt water in the oceans." },
  { id: "h2o-016", skill: "sci-water", q: "Where is most of Earth's FRESH water found?", choices: ["in rivers", "frozen in glaciers and ice caps", "in lakes", "in the clouds"], answer: 1, explain: "Most fresh water is locked up as ice in glaciers and ice caps, which is why fresh water we can use is precious." },
  { id: "h2o-017", skill: "sci-water", q: "What is a watershed?", choices: ["a building that stores drinking water", "a kind of cloud", "a dam on a river", "an area of land that drains into a particular river, lake, or bay"], answer: 3, explain: "All the rain that falls on a watershed flows downhill into the same body of water." },
  { id: "h2o-018", skill: "sci-water", q: "Fairfax County is part of which large watershed?", choices: ["the Chesapeake Bay watershed", "the Gulf of Mexico watershed", "the Pacific Ocean watershed", "the Great Lakes watershed"], answer: 0, explain: "Fairfax's streams flow into the Potomac River, which flows into the Chesapeake Bay. Over half of Virginia drains to the Bay." },
  { id: "h2o-019", skill: "sci-water", q: "Fertilizer from a lawn in Fairfax washes into a nearby stream. Where might it end up?", choices: ["It stays on the lawn", "in the Pacific Ocean", "in the Potomac River and then the Chesapeake Bay", "in the clouds"], answer: 2, explain: "Water flows downhill from small streams to bigger rivers and then into the Bay, carrying pollution with it." },
  { id: "h2o-020", skill: "sci-water", q: "Too much fertilizer washing into the Chesapeake Bay can cause ___.", choices: ["too much algae to grow, using up the oxygen fish and crabs need", "more fish to hatch", "cleaner, clearer water", "the Bay to freeze"], answer: 0, explain: "Fertilizer feeds algae. When huge amounts of algae die and rot, the oxygen in the water gets used up, harming fish and crabs." },
  { id: "h2o-021", skill: "sci-water", q: "The Chesapeake Bay is an estuary. What does that mean?", choices: ["It is made only of fresh water", "It is an underground lake", "It is frozen most of the year", "Fresh water from rivers mixes with salt water from the ocean"], answer: 3, explain: "An estuary is where rivers meet the sea, so the water is a brackish mix of fresh and salt water." },
  { id: "h2o-022", skill: "sci-water", q: "Rainwater that soaks into the ground and fills the spaces between soil and rock is called ___.", choices: ["runoff", "groundwater", "water vapor", "condensation"], answer: 1, explain: "Groundwater is water stored underground. Many people get their drinking water from wells that reach it." },
  { id: "h2o-023", skill: "sci-water", q: "What is an aquifer?", choices: ["a lake at the top of a mountain", "a kind of cloud", "an underground layer of rock or sediment that holds groundwater", "the mouth of a river"], answer: 2, explain: "An aquifer is like an underground sponge of rock, sand, or gravel that stores water people can pump out with wells." },
  { id: "h2o-024", skill: "sci-water", q: "After a heavy rain, water flows across a paved parking lot into a storm drain instead of soaking into the ground. This water is called ___.", choices: ["runoff", "infiltration", "transpiration", "condensation"], answer: 0, explain: "Runoff is water that flows over the surface. Pavement doesn't let water soak in, so there is more runoff." },
  { id: "h2o-025", skill: "sci-water", q: "The top of the underground zone where the soil and rock are completely filled with water is called the ___.", choices: ["dew point", "watershed", "flood plain", "water table"], answer: 3, explain: "The water table is the top of the saturated zone. A well must be dug below the water table to reach water." },

  // ===== Science: Energy (sci-energy) =====
  { id: "en-001", skill: "sci-energy", q: "A boulder sitting still at the top of a hill has mostly ___ energy.", choices: ["potential", "kinetic", "sound", "electrical"], answer: 0, explain: "Potential energy is stored energy. Because of its height, the boulder could roll down if pushed." },
  { id: "en-002", skill: "sci-energy", q: "A soccer ball rolling across the field has ___.", choices: ["potential energy only", "no energy at all", "kinetic energy", "nuclear energy"], answer: 2, explain: "Kinetic energy is the energy of motion. Anything that is moving has kinetic energy." },
  { id: "en-003", skill: "sci-energy", q: "As a roller coaster speeds down the first big hill, its potential energy changes mostly into ___.", choices: ["kinetic energy", "chemical energy", "nuclear energy", "more potential energy"], answer: 0, explain: "As the coaster loses height, it loses potential energy and gains speed, which is kinetic energy." },
  { id: "en-004", skill: "sci-energy", q: "At which point does a swinging pendulum have the MOST kinetic energy?", choices: ["at the highest point of its swing", "when it is stopped", "it never has kinetic energy", "at the bottom of its swing"], answer: 3, explain: "The pendulum moves fastest at the bottom, so its kinetic energy is greatest there. At the top it stops for an instant and has the most potential energy." },
  { id: "en-005", skill: "sci-energy", q: "When you turn on a flashlight, which energy changes happen?", choices: ["light energy to chemical energy", "chemical energy (battery) to electrical energy to light energy", "sound energy to light energy", "kinetic energy to nuclear energy"], answer: 1, explain: "The battery stores chemical energy. It becomes electrical energy in the wires, then light (and a little heat) in the bulb." },
  { id: "en-006", skill: "sci-energy", q: "A toaster changes ___.", choices: ["electrical energy into thermal (heat) energy", "thermal energy into electrical energy", "light energy into sound energy", "chemical energy into nuclear energy"], answer: 0, explain: "Electricity flows through the toaster's wires, which get hot and toast the bread." },
  { id: "en-007", skill: "sci-energy", q: "A plant uses sunlight to make its food (sugar). What energy change is this?", choices: ["chemical energy into light energy", "thermal energy into sound energy", "light energy into chemical energy", "kinetic energy into electrical energy"], answer: 2, explain: "In photosynthesis, plants capture light energy and store it as chemical energy in sugar." },
  { id: "en-008", skill: "sci-energy", q: "Which statement about energy is true?", choices: ["Energy gets used up and disappears", "Energy can be created from nothing", "Only moving objects have energy", "Energy can change forms, but it is not created or destroyed"], answer: 3, explain: "This is the law of conservation of energy. Energy just changes from one form to another." },
  { id: "en-009", skill: "sci-energy", q: "Which is a renewable energy resource?", choices: ["wind", "coal", "oil", "natural gas"], answer: 0, explain: "Wind is renewable because it won't run out. Coal, oil, and natural gas are fossil fuels that can be used up." },
  { id: "en-010", skill: "sci-energy", q: "Why are coal, oil, and natural gas called nonrenewable resources?", choices: ["The sun makes new ones every day", "They never run out", "They took millions of years to form and can't be replaced quickly", "They are made of water"], answer: 2, explain: "Fossil fuels form over millions of years. Once we use them up, they can't be replaced in our lifetimes." },
  { id: "en-011", skill: "sci-energy", q: "Fossil fuels such as coal and oil formed from ___.", choices: ["volcanic lava", "the remains of ancient plants and animals over millions of years", "sunlight collected in one day", "ocean salt"], answer: 1, explain: "Ancient plants and tiny sea creatures were buried and squeezed by heat and pressure over millions of years, becoming fossil fuels." },
  { id: "en-012", skill: "sci-energy", q: "You leave a metal spoon in a pot of hot soup, and soon the handle feels hot. This heat transfer is ___.", choices: ["conduction", "convection", "radiation", "evaporation"], answer: 0, explain: "Conduction is heat moving through direct contact, from molecule to molecule, through the metal." },
  { id: "en-013", skill: "sci-energy", q: "In a pot of boiling water, hot water rises and cooler water sinks in a loop. This heat transfer is ___.", choices: ["radiation", "conduction", "insulation", "convection"], answer: 3, explain: "Convection is heat carried by moving liquids or gases. It's the same process that makes warm air rise." },
  { id: "en-014", skill: "sci-energy", q: "You feel the sun's warmth on your face even though space has no air. This heat transfer is ___.", choices: ["conduction", "convection", "insulation", "radiation"], answer: 3, explain: "Radiation is energy traveling as waves. It doesn't need air or anything to touch, so it can cross empty space." },
  { id: "en-015", skill: "sci-energy", q: "Which pair lists a renewable resource and then a nonrenewable resource, in that order?", choices: ["coal; solar", "solar; coal", "oil; natural gas", "wind; sunlight"], answer: 1, explain: "Solar energy is renewable (the sun keeps shining) and coal is nonrenewable (it took millions of years to form)." },

  // ===== Social Studies: Geography (ss-geo) =====
  { id: "geo-001", skill: "ss-geo", q: "Which are the four cardinal directions?", choices: ["northeast, northwest, southeast, southwest", "north, south, east, west", "up, down, left, right", "latitude, longitude, scale, key"], answer: 1, explain: "The cardinal directions are the four main directions: north, south, east, and west." },
  { id: "geo-002", skill: "ss-geo", q: "Northeast, northwest, southeast, and southwest are called ___ directions.", choices: ["cardinal", "intermediate", "absolute", "polar"], answer: 1, explain: "Intermediate directions are halfway between the cardinal directions. Northeast is between north and east." },
  { id: "geo-003", skill: "ss-geo", q: "Which map symbol shows directions?", choices: ["map key (legend)", "scale", "compass rose", "title"], answer: 2, explain: "A compass rose shows north, south, east, and west, and often the intermediate directions too." },
  { id: "geo-004", skill: "ss-geo", q: "Which part of a map helps you figure out the real distance between two places?", choices: ["the compass rose", "the legend", "the title", "the scale"], answer: 3, explain: "A map scale shows how a distance on the map compares to real distance, like 1 inch = 100 miles." },
  { id: "geo-005", skill: "ss-geo", q: "Which part of a map explains what the symbols and colors mean?", choices: ["the scale", "the compass rose", "the legend (key)", "the lines of latitude"], answer: 2, explain: "The legend, or key, tells you what each symbol and color on the map stands for." },
  { id: "geo-006", skill: "ss-geo", q: "Lines of latitude ___.", choices: ["run north and south and measure distance east or west of the Prime Meridian", "run east and west and measure distance north or south of the Equator", "show the elevation of mountains", "show where rivers flow"], answer: 1, explain: "Latitude lines run side to side (east-west) like the rungs of a ladder, and measure how far north or south of the Equator a place is." },
  { id: "geo-007", skill: "ss-geo", q: "Lines of longitude measure distance east or west of the ___.", choices: ["Equator", "Tropic of Cancer", "Prime Meridian", "Arctic Circle"], answer: 2, explain: "Longitude lines run from pole to pole and are numbered east or west of the Prime Meridian (0° longitude)." },
  { id: "geo-008", skill: "ss-geo", q: "The Equator is at ___ latitude.", choices: ["0°", "90°N", "180°", "45°N"], answer: 0, explain: "The Equator is the starting line for latitude, 0°. The North Pole is 90°N." },
  { id: "geo-009", skill: "ss-geo", q: "The Prime Meridian (0° longitude) divides Earth into which two hemispheres?", choices: ["Northern and Southern", "Eastern and Western", "Arctic and Antarctic", "Atlantic and Pacific"], answer: 1, explain: "The Prime Meridian splits Earth into the Eastern and Western Hemispheres. The Equator splits it into Northern and Southern." },
  { id: "geo-010", skill: "ss-geo", q: "Which line divides Earth into the Northern and Southern Hemispheres?", choices: ["the Prime Meridian", "the International Date Line", "the Tropic of Capricorn", "the Equator"], answer: 3, explain: "The Equator circles the middle of Earth, halfway between the North and South Poles." },
  { id: "geo-011", skill: "ss-geo", q: "North America is located in which two hemispheres?", choices: ["Southern and Eastern", "Northern and Eastern", "Northern and Western", "Southern and Western"], answer: 2, explain: "North America is north of the Equator and west of the Prime Meridian." },
  { id: "geo-012", skill: "ss-geo", q: "Which of these gives a place's exact (absolute) location?", choices: ["\"near the river\"", "its latitude and longitude", "\"two blocks from the library\"", "the color it is on the map"], answer: 1, explain: "Latitude and longitude give an exact address on the globe. 'Near the river' is a relative location." },
  { id: "geo-013", skill: "ss-geo", q: "A place is located at 38°N, 77°W. What does this tell you?", choices: ["It is south of the Equator and east of the Prime Meridian", "It is north of the Equator and east of the Prime Meridian", "It is south of the Equator and west of the Prime Meridian", "It is north of the Equator and west of the Prime Meridian"], answer: 3, explain: "N means north of the Equator and W means west of the Prime Meridian. (38°N, 77°W is close to Washington, D.C.)" },
  { id: "geo-014", skill: "ss-geo", q: "Which region is low, flat land along the Atlantic Ocean and Gulf of Mexico, with many good harbors?", choices: ["Great Plains", "Canadian Shield", "Coastal Plain", "Basin and Range"], answer: 2, explain: "The Coastal Plain is the broad lowland along the Atlantic and Gulf coasts. Its harbors made it a good place for settlements." },
  { id: "geo-015", skill: "ss-geo", q: "Which region is an old, eroded mountain range that stretches from Canada to Alabama?", choices: ["Rocky Mountains", "Appalachian Mountains", "Coastal Range", "Canadian Shield"], answer: 1, explain: "The Appalachians are the oldest mountains in North America. Millions of years of erosion wore them down and rounded them." },
  { id: "geo-016", skill: "ss-geo", q: "Which region wraps around Hudson Bay in a horseshoe shape and has very old rock, hills worn down by glaciers, and many lakes?", choices: ["Interior Lowlands", "Great Plains", "Coastal Plain", "Canadian Shield"], answer: 3, explain: "The Canadian Shield is made of some of the oldest rock on Earth, scraped by glaciers into low hills and lakes." },
  { id: "geo-017", skill: "ss-geo", q: "Which region has rolling flatlands with many rivers, broad river valleys, and grassy hills?", choices: ["Great Plains", "Interior Lowlands", "Basin and Range", "Coastal Range"], answer: 1, explain: "The Interior Lowlands lie in the middle of the continent between the Appalachians and the Great Plains." },
  { id: "geo-018", skill: "ss-geo", q: "Which region is a flat grassland that slowly rises in elevation as you go west?", choices: ["Great Plains", "Interior Lowlands", "Coastal Plain", "Canadian Shield"], answer: 0, explain: "The Great Plains are wide grasslands that gradually get higher as they approach the Rocky Mountains." },
  { id: "geo-019", skill: "ss-geo", q: "Which region has rugged mountains stretching from Alaska almost to Mexico, is higher and younger than the Appalachians, and contains the Continental Divide?", choices: ["Appalachian Mountains", "Coastal Range", "Rocky Mountains", "Canadian Shield"], answer: 2, explain: "The Rocky Mountains are tall, rugged, and young. The Continental Divide runs along them." },
  { id: "geo-020", skill: "ss-geo", q: "Which region has isolated mountain ranges separated by low valleys and includes Death Valley, the lowest point in North America?", choices: ["Great Plains", "Coastal Plain", "Interior Lowlands", "Basin and Range"], answer: 3, explain: "The Basin and Range has varying elevation: mountain 'ranges' with low 'basins' between them, like Death Valley." },
  { id: "geo-021", skill: "ss-geo", q: "Which region has rugged mountains along the Pacific coast, from California to Canada, with fertile valleys?", choices: ["Rocky Mountains", "Coastal Range", "Appalachian Mountains", "Basin and Range"], answer: 1, explain: "The Coastal Range runs right along the Pacific Ocean. Its fertile valleys are good for farming." },
  { id: "geo-022", skill: "ss-geo", q: "What does the Continental Divide in the Rocky Mountains determine?", choices: ["where the Equator is", "where hurricanes form", "the direction that rivers flow", "the border between the U.S. and Canada"], answer: 2, explain: "Rivers east of the Divide generally flow east toward the Gulf of Mexico and Atlantic, and rivers west of it generally flow toward the Pacific." },
  { id: "geo-023", skill: "ss-geo", q: "Jamestown and Virginia Beach are located in which region of North America?", choices: ["Appalachian Mountains", "Coastal Plain", "Interior Lowlands", "Canadian Shield"], answer: 1, explain: "Eastern Virginia, near the Atlantic and Chesapeake Bay, is part of the Coastal Plain. In Virginia it is called the Tidewater." },
  { id: "geo-024", skill: "ss-geo", q: "Which region lies between the Appalachian Mountains and the Great Plains?", choices: ["Interior Lowlands", "Coastal Plain", "Basin and Range", "Coastal Range"], answer: 0, explain: "Going west from the Appalachians, you reach the Interior Lowlands, then the Great Plains." },
  { id: "geo-025", skill: "ss-geo", q: "Which region lies between the Rocky Mountains and the Coastal Range?", choices: ["Great Plains", "Interior Lowlands", "Canadian Shield", "Basin and Range"], answer: 3, explain: "The Basin and Range sits west of the Rockies and east of the Coastal Range." },
  { id: "geo-026", skill: "ss-geo", q: "Which list names the five Great Lakes?", choices: ["Superior, Michigan, Huron, Erie, Champlain", "Superior, Victoria, Huron, Erie, Ontario", "Superior, Michigan, Huron, Erie, Ontario", "Michigan, Huron, Erie, Ontario, Great Salt Lake"], answer: 2, explain: "Remember HOMES: Huron, Ontario, Michigan, Erie, Superior." },
  { id: "geo-027", skill: "ss-geo", q: "Which river flows south through the middle of the United States, empties into the Gulf of Mexico, and has long been a major transportation route?", choices: ["Columbia River", "St. Lawrence River", "Colorado River", "Mississippi River"], answer: 3, explain: "Together with the Missouri River, the Mississippi forms the largest river system in North America." },
  { id: "geo-028", skill: "ss-geo", q: "Which river begins in the Rocky Mountains and flows into the Mississippi River?", choices: ["Rio Grande", "Missouri River", "St. Lawrence River", "Columbia River"], answer: 1, explain: "The Missouri River starts in the Rockies and joins the Mississippi. It later became a route for exploring the West." },
  { id: "geo-029", skill: "ss-geo", q: "Which river begins in the Appalachian Mountains, flows into the Mississippi River, and became a 'gateway to the West'?", choices: ["Columbia River", "Ohio River", "Colorado River", "Rio Grande"], answer: 1, explain: "Settlers floated down the Ohio River to move west across the Appalachian Mountains." },
  { id: "geo-030", skill: "ss-geo", q: "Which river is located in the Northwest and flows into the Pacific Ocean?", choices: ["Mississippi River", "Ohio River", "St. Lawrence River", "Columbia River"], answer: 3, explain: "The Columbia River flows through the Pacific Northwest to the Pacific Ocean." },
  { id: "geo-031", skill: "ss-geo", q: "Which river in the Southwest carved the Grand Canyon?", choices: ["Ohio River", "Missouri River", "St. Lawrence River", "Colorado River"], answer: 3, explain: "Over millions of years, the Colorado River cut down through rock to form the Grand Canyon." },
  { id: "geo-032", skill: "ss-geo", q: "Which river forms the border between Texas and Mexico?", choices: ["Rio Grande", "Colorado River", "Columbia River", "Ohio River"], answer: 0, explain: "The Rio Grande forms the border between Texas and Mexico and flows into the Gulf of Mexico." },
  { id: "geo-033", skill: "ss-geo", q: "Which river connects the Great Lakes to the Atlantic Ocean and forms part of the border between the U.S. and Canada?", choices: ["Mississippi River", "St. Lawrence River", "Rio Grande", "Columbia River"], answer: 1, explain: "The St. Lawrence River lets ships travel between the Great Lakes and the Atlantic Ocean." },
  { id: "geo-034", skill: "ss-geo", q: "Which body of water lies south of the United States and receives the Mississippi River?", choices: ["Arctic Ocean", "Hudson Bay", "Gulf of Mexico", "Pacific Ocean"], answer: 2, explain: "The Mississippi River empties into the Gulf of Mexico, south of the U.S." },
  { id: "geo-035", skill: "ss-geo", q: "Which ocean is along the east coast of the United States?", choices: ["Pacific Ocean", "Atlantic Ocean", "Arctic Ocean", "Indian Ocean"], answer: 1, explain: "The Atlantic Ocean is on the east coast, the side where Virginia is. The Pacific is on the west coast." },
  { id: "geo-036", skill: "ss-geo", q: "Which ocean lies north of North America?", choices: ["Pacific Ocean", "Atlantic Ocean", "Arctic Ocean", "Indian Ocean"], answer: 2, explain: "The cold Arctic Ocean is to the north, near Alaska and northern Canada." },
  { id: "geo-037", skill: "ss-geo", q: "Why did many early towns and cities grow up along rivers and coasts?", choices: ["Rivers kept away all diseases", "Land near water had no trees to clear", "Mountains near the coast were warmer", "Water provided transportation, trade, fresh water, and food"], answer: 3, explain: "Before roads and railroads, boats were the easiest way to move people and goods, and rivers also gave water and fish." },
  { id: "geo-038", skill: "ss-geo", q: "The Appalachian Mountains were a barrier to early colonists. What does that mean?", choices: ["They made it harder for colonists to move west", "They were the flattest land for farming", "They blocked all trade with Europe", "They were where the first colonists landed"], answer: 0, explain: "The mountains were hard to cross, so for many years most colonists stayed on the Coastal Plain east of them." },
  { id: "geo-039", skill: "ss-geo", q: "Ships sailing up rivers from the Atlantic had to stop at waterfalls where the Coastal Plain meets higher land (the Fall Line). What often grew at those spots?", choices: ["large cattle ranches", "cities and trading towns", "fishing villages on the open ocean", "gold-mining camps"], answer: 1, explain: "Goods had to be unloaded where ships could go no farther, so towns grew there. Richmond, Virginia is on the Fall Line." },
  { id: "geo-040", skill: "ss-geo", q: "The Great Plains later became known for growing wheat and raising cattle. Which feature of the land made this possible?", choices: ["thick forests for lumber", "the most rainfall in North America", "wide, flat grasslands", "rocky, glacier-scraped hills"], answer: 2, explain: "Flat, open grasslands are good for grazing cattle and for planting huge fields of grain." },

  // ===== Social Studies: Indigenous Peoples of North America (ss-indig) =====
  { id: "ind-001", skill: "ss-indig", q: "Where did the Inuit live?", choices: ["the Southwest desert", "the Great Plains", "the Arctic, in present-day Alaska and northern Canada", "Virginia's Coastal Plain"], answer: 2, explain: "The Inuit live in the Arctic, where it is below freezing for much of the year." },
  { id: "ind-002", skill: "ss-indig", q: "Which foods did the Inuit mainly depend on?", choices: ["corn, beans, and squash from large farms", "seals, whales, fish, and caribou", "deer and turkey from thick forests", "buffalo from the grasslands"], answer: 1, explain: "Few plants grow in the Arctic, so the Inuit hunted animals from the sea and land." },
  { id: "ind-003", skill: "ss-indig", q: "Why did the Inuit rely on hunting instead of farming?", choices: ["The land was all desert sand", "There was too much rain", "There were no animals nearby", "The Arctic is very cold, with frozen ground and a very short growing season"], answer: 3, explain: "Crops can't grow well in frozen ground, so the Inuit got their food from animals." },
  { id: "ind-004", skill: "ss-indig", q: "What kind of clothing did the Inuit make?", choices: ["light cotton clothing", "warm clothing made from animal skins and furs", "clothing woven from cedar bark", "clothing woven from cotton grown in the desert"], answer: 1, explain: "Furs and skins from animals like seals and caribou kept the Inuit warm in the freezing Arctic." },
  { id: "ind-005", skill: "ss-indig", q: "In winter, some Inuit families built temporary homes from blocks of snow and ice. What are these called?", choices: ["igloos", "tipis", "longhouses", "plank houses"], answer: 0, explain: "Igloos were built from the material the Arctic had most of: snow. Inuit also used homes made of sod, stone, and skins." },
  { id: "ind-006", skill: "ss-indig", q: "The Kwakiutl lived along the ___, where there was lots of rain, thick forests, and the ocean.", choices: ["Great Plains", "Southwest desert", "Northwest coast of the Pacific Ocean", "Arctic sea ice"], answer: 2, explain: "The Kwakiutl lived in the Pacific Northwest, in present-day British Columbia, Canada. The climate there is mild and rainy." },
  { id: "ind-007", skill: "ss-indig", q: "What kind of homes did the Kwakiutl build?", choices: ["adobe houses", "tipis", "igloos", "plank houses made of cedar wood"], answer: 3, explain: "The thick forests gave the Kwakiutl tall cedar trees, which they split into planks for large houses." },
  { id: "ind-008", skill: "ss-indig", q: "The Kwakiutl had plenty of food without much farming. Where did most of their food come from?", choices: ["buffalo hunts on the plains", "the ocean, rivers (especially salmon), and the forests", "large fields of cotton", "corn fields in the desert"], answer: 1, explain: "The rivers were full of salmon and the sea and forests had plenty of food, so the Kwakiutl fished, hunted, and gathered." },
  { id: "ind-009", skill: "ss-indig", q: "The Kwakiutl carved tall cedar poles with figures that showed family history and important stories. These are called ___.", choices: ["totem poles", "kayaks", "wampum belts", "pueblos"], answer: 0, explain: "Totem poles were carved from cedar, a resource the Northwest forests provided." },
  { id: "ind-010", skill: "ss-indig", q: "The Lakota lived mainly on the ___.", choices: ["Arctic coast", "Northwest coast", "Southwest mesas", "Great Plains"], answer: 3, explain: "The Lakota lived on the Great Plains (and Interior Lowlands), a wide, dry grassland." },
  { id: "ind-011", skill: "ss-indig", q: "Which statement about the Lakota and the buffalo (bison) is true?", choices: ["They used buffalo to pull plows on large farms", "They used the buffalo for food, clothing, tipi covers, and tools", "They hunted buffalo only for sport", "They traded buffalo to the Inuit for seals"], answer: 1, explain: "The buffalo provided almost everything the Lakota needed, and they used nearly every part of the animal." },
  { id: "ind-012", skill: "ss-indig", q: "Why did the Lakota live in tipis?", choices: ["Tipis were made of stone and lasted for centuries", "Tipis kept out the Arctic cold", "Tipis could be packed up quickly to follow the buffalo herds", "Tipis were built on cliffs"], answer: 2, explain: "The Lakota moved often to follow the buffalo, so they needed homes made of hides and poles that were easy to move." },
  { id: "ind-013", skill: "ss-indig", q: "Why did the Pueblo build with adobe while the Kwakiutl built with cedar wood?", choices: ["The Pueblo traded with Europeans for adobe", "Cedar was not allowed in the Southwest", "Each group used the natural resources found in its own environment", "The Kwakiutl lived in a desert"], answer: 2, explain: "The dry Southwest had clay and few trees, while the Northwest had huge forests. People built with what was around them." },
  { id: "ind-014", skill: "ss-indig", q: "The Pueblo people lived in the Southwest, in present-day ___.", choices: ["Alaska", "New York", "New Mexico and Arizona", "Virginia"], answer: 2, explain: "The Pueblo lived in the desert Southwest, a dry land of canyons and mesas." },
  { id: "ind-015", skill: "ss-indig", q: "Pueblo homes were made of adobe. What is adobe?", choices: ["cedar planks", "sun-dried bricks made of clay and straw", "buffalo hides", "blocks of snow"], answer: 1, explain: "The Southwest has few trees but lots of clay and sun, so the Pueblo made sun-dried bricks and built homes several stories tall." },
  { id: "ind-016", skill: "ss-indig", q: "Even though the Southwest is very dry, the Pueblo people farmed. Which crops did they grow?", choices: ["rice in flooded fields", "apples and oranges", "wheat on the frozen tundra", "corn, beans, and squash"], answer: 3, explain: "The Pueblo grew corn, beans, and squash, carefully using the little water they had." },
  { id: "ind-017", skill: "ss-indig", q: "The Haudenosaunee (Iroquois) of the Eastern Woodlands lived in long, bark-covered homes shared by several families. These homes are called ___.", choices: ["igloos", "adobe pueblos", "tipis", "longhouses"], answer: 3, explain: "The Eastern Woodlands had many trees, so the Haudenosaunee built longhouses from wooden poles covered with bark." },
  { id: "ind-018", skill: "ss-indig", q: "The Haudenosaunee nations formed a confederacy. What does that mean?", choices: ["They all lived in one large city", "Several nations united to keep peace and make decisions together", "They were governed by a European king", "They moved every season to follow buffalo"], answer: 1, explain: "The Haudenosaunee Confederacy joined several nations under the Great Law of Peace so they could work together instead of fighting." },
  { id: "ind-019", skill: "ss-indig", q: "When the English arrived at Jamestown in 1607, the Powhatan people lived in which region of Virginia?", choices: ["Appalachian Mountains", "Great Plains", "Basin and Range", "Coastal Plain (Tidewater)"], answer: 3, explain: "The Powhatan lived in the Tidewater, part of the Coastal Plain, near the rivers that flow into the Chesapeake Bay." },
  { id: "ind-020", skill: "ss-indig", q: "The Powhatan built homes called yehakins from bent saplings covered with bark or woven mats. How did they get their food?", choices: ["by hunting whales on sea ice", "by farming corn, fishing, and hunting deer", "by herding cattle", "by trading for food from Spain"], answer: 1, explain: "The Tidewater's rich soil, rivers, and forests let the Powhatan farm, fish, and hunt." },

  // ===== Social Studies: West African Empires (ss-africa) =====
  { id: "afr-001", skill: "ss-africa", q: "In what order did the three great West African empires rise?", choices: ["Mali, Ghana, Songhai", "Songhai, Mali, Ghana", "Ghana, Mali, Songhai", "Ghana, Songhai, Mali"], answer: 2, explain: "First came Ghana, then Mali, then Songhai. Remember: Good Morning, Sun (Ghana, Mali, Songhai)." },
  { id: "afr-002", skill: "ss-africa", q: "The West African empires grew rich mainly by trading ___.", choices: ["tea and silk", "gold and salt", "tobacco and cotton", "furs and timber"], answer: 1, explain: "West Africa had gold, and traders from the north brought salt. Controlling this trade made the empires rich." },
  { id: "afr-003", skill: "ss-africa", q: "Why was salt so valuable in West Africa?", choices: ["It was used to build houses", "It could be turned into gold", "It was burned as fuel", "It kept food from spoiling, and people needed it in the hot climate"], answer: 3, explain: "Salt preserved food and replaced the salt people lost by sweating in the heat. It was so valuable that traders exchanged it for gold." },
  { id: "afr-004", skill: "ss-africa", q: "In the gold-salt trade, salt mostly came from ___, and gold mostly came from ___.", choices: ["the Sahara Desert in the north; mines in the south of West Africa", "mines in the south of West Africa; the Sahara Desert in the north", "Europe; India", "the Nile River; the Atlantic Ocean"], answer: 0, explain: "Salt was mined in the Sahara to the north, and gold was mined in the south of West Africa. The empires controlled the trade routes between them." },
  { id: "afr-005", skill: "ss-africa", q: "Why were camels so important to trans-Saharan trade?", choices: ["They are fast swimmers", "They eat salt instead of plants", "They can travel long distances through the desert with little water", "They could pull boats up rivers"], answer: 2, explain: "Camels can go many days without water and walk well on sand, so they could carry goods across the Sahara." },
  { id: "afr-006", skill: "ss-africa", q: "Caravans of traders crossed which desert to trade between North Africa and West Africa?", choices: ["the Gobi", "the Sahara", "the Mojave", "the Kalahari"], answer: 1, explain: "The Sahara is the huge desert in northern Africa. 'Trans-Saharan' means 'across the Sahara.'" },
  { id: "afr-007", skill: "ss-africa", q: "A group of traders traveling together, often with camels, is called a ___.", choices: ["fleet", "legion", "confederacy", "caravan"], answer: 3, explain: "Traders crossed the desert in caravans for safety, sometimes with thousands of camels." },
  { id: "afr-008", skill: "ss-africa", q: "How did the empire of Ghana grow rich?", choices: ["by taxing the gold and salt trade that passed through its land", "by growing tobacco", "by conquering Europe", "by selling camels to Spain"], answer: 0, explain: "Ghana's kings controlled the trade routes and taxed the goods traders carried through." },
  { id: "afr-009", skill: "ss-africa", q: "Who founded the Mali Empire after defeating a rival king?", choices: ["Mansa Musa", "Askia Muhammad", "Sundiata", "Christopher Columbus"], answer: 2, explain: "Sundiata (Sundiata Keita) is remembered as the founder of Mali. His story is still told by West African storytellers called griots." },
  { id: "afr-010", skill: "ss-africa", q: "Mansa Musa of Mali is most famous for ___.", choices: ["founding the empire of Ghana", "his pilgrimage to Mecca, where he gave away so much gold that its value dropped in Cairo", "sailing to the Americas", "building the pyramids of Egypt"], answer: 1, explain: "On his hajj in 1324, Mansa Musa traveled with a huge caravan and so much gold that he showed the world how rich Mali was." },
  { id: "afr-011", skill: "ss-africa", q: "Mansa Musa's pilgrimage to Mecca showed that he was a follower of ___.", choices: ["Christianity", "Buddhism", "Hinduism", "Islam"], answer: 3, explain: "A pilgrimage (hajj) to Mecca is an important duty in Islam." },
  { id: "afr-012", skill: "ss-africa", q: "The city of Timbuktu became famous as ___.", choices: ["a fort on the Atlantic coast", "a Spanish colony", "a center of learning and trade, with mosques, scholars, and many books", "a port on the Nile River"], answer: 2, explain: "In Mali and Songhai, Timbuktu was a busy trading city where scholars came to study and books were highly valued." },
  { id: "afr-013", skill: "ss-africa", q: "After his pilgrimage, Mansa Musa brought scholars and architects back to Mali. What did they help build in Timbuktu?", choices: ["castles for European kings", "mosques and centers of learning", "tobacco plantations", "pyramids"], answer: 1, explain: "Mansa Musa's support helped make Timbuktu a center of Islamic learning." },
  { id: "afr-014", skill: "ss-africa", q: "Which of the three West African empires was the largest?", choices: ["Ghana", "Mali", "Songhai", "Egypt"], answer: 2, explain: "Songhai, the last of the three, grew to be the largest." },
  { id: "afr-015", skill: "ss-africa", q: "Askia Muhammad, a ruler of Songhai, is known for ___.", choices: ["founding the empire of Mali", "crossing the Atlantic Ocean", "ending the gold-salt trade", "organizing a strong government, expanding the empire, and supporting Islam and learning"], answer: 3, explain: "Askia Muhammad divided Songhai into provinces with governors and encouraged learning in cities like Timbuktu." },
  { id: "afr-016", skill: "ss-africa", q: "How did Islam spread into West Africa?", choices: ["through Spanish explorers", "through Muslim traders and scholars traveling the trans-Saharan trade routes", "through English colonists", "through Viking raids"], answer: 1, explain: "Trade routes carried ideas and beliefs along with goods. Many West African rulers and traders became Muslim." },
  { id: "afr-017", skill: "ss-africa", q: "Ghana, Mali, and Songhai were located in ___ Africa, south of the Sahara Desert.", choices: ["western", "eastern", "southern", "northern"], answer: 0, explain: "All three empires were in West Africa, between the Sahara Desert and the forests to the south." },
  { id: "afr-018", skill: "ss-africa", q: "Which river was important to Mali and Songhai for trade, farming, and travel?", choices: ["Nile River", "Amazon River", "Niger River", "Mississippi River"], answer: 2, explain: "The Niger River flows through West Africa. Cities like Timbuktu and Gao grew near it." },
  { id: "afr-019", skill: "ss-africa", q: "Which statement correctly compares Ghana and Mali?", choices: ["Ghana was much larger than Mali", "Neither used trade routes across the Sahara", "Both were located in South America", "Both grew wealthy from trade in gold and salt"], answer: 3, explain: "Ghana and Mali both got rich by controlling the gold-salt trade. Mali grew larger than Ghana." },
  { id: "afr-020", skill: "ss-africa", q: "Mansa Musa ruled which empire?", choices: ["Ghana", "Mali", "Songhai", "Egypt"], answer: 1, explain: "'Mansa' means king or emperor. Mansa Musa ruled Mali at the height of its wealth." },

  // ===== Social Studies: European Exploration (ss-explore) =====
  { id: "exp-001", skill: "ss-explore", q: "The main reasons Europeans explored are often summed up as ___.", choices: ["fish, furs, and farming", "peace, law, and order", "God, gold, and glory", "rain, wind, and snow"], answer: 2, explain: "God = religion (spreading Christianity), gold = wealth and trade, glory = fame and competition among nations." },
  { id: "exp-002", skill: "ss-explore", q: "Many European explorers wanted to find a faster water route to Asia because ___.", choices: ["they wanted to escape cold weather", "they wanted valuable spices and silk from Asia", "they hoped to find new planets", "they wanted to reach the South Pole"], answer: 1, explain: "Spices and silk sold for high prices in Europe. A faster sea route meant bigger profits, which is an economic reason." },
  { id: "exp-003", skill: "ss-explore", q: "Which is an example of a RELIGIOUS reason for exploration?", choices: ["finding gold", "claiming land for the king", "finding spices", "spreading Christianity"], answer: 3, explain: "Many explorers and missionaries wanted to spread Christianity to the people they met." },
  { id: "exp-004", skill: "ss-explore", q: "Spain, France, England, and the Netherlands raced to claim land in the Americas. This shows which motivation?", choices: ["competition for empire and glory", "a desire to end slavery", "religious freedom for Pilgrims", "escaping the Ice Age"], answer: 0, explain: "European nations competed to be the most powerful, and claiming land made them richer and more famous." },
  { id: "exp-005", skill: "ss-explore", q: "Christopher Columbus sailed in 1492 for which country?", choices: ["Portugal", "Spain", "England", "France"], answer: 1, explain: "Columbus was from Genoa, Italy, but King Ferdinand and Queen Isabella of Spain paid for his voyage." },
  { id: "exp-006", skill: "ss-explore", q: "In 1492, Columbus reached islands in the ___, but he believed he had reached Asia.", choices: ["Pacific Ocean", "Arctic Ocean", "Caribbean Sea", "Mediterranean Sea"], answer: 2, explain: "Columbus landed in the Caribbean and claimed the land for Spain. He thought he was near the Indies (Asia), which is why he called the people 'Indians.'" },
  { id: "exp-007", skill: "ss-explore", q: "Which Spanish explorer explored and claimed Florida for Spain?", choices: ["Jacques Cartier", "John Cabot", "Henry Hudson", "Juan Ponce de León"], answer: 3, explain: "Ponce de León explored Florida in 1513 and claimed it for Spain. Legends say he was looking for a Fountain of Youth." },
  { id: "exp-008", skill: "ss-explore", q: "Jacques Cartier explored the ___ River and claimed land for France.", choices: ["Mississippi", "St. Lawrence", "Hudson", "Rio Grande"], answer: 1, explain: "Cartier sailed up the St. Lawrence River in present-day Canada, giving France a claim to the area." },
  { id: "exp-009", skill: "ss-explore", q: "Who founded Quebec in 1608 and is called the 'Father of New France'?", choices: ["Jacques Cartier", "Hernando de Soto", "John Smith", "Samuel de Champlain"], answer: 3, explain: "Samuel de Champlain founded Quebec, the first permanent French settlement in North America." },
  { id: "exp-010", skill: "ss-explore", q: "John Cabot was an Italian sailor who explored eastern Canada and claimed land for ___.", choices: ["Spain", "France", "the Netherlands", "England"], answer: 3, explain: "Cabot sailed for England in 1497. His voyage gave England a claim to land in North America." },
  { id: "exp-011", skill: "ss-explore", q: "Henry Hudson explored a river in present-day New York for the Netherlands, giving the Dutch a claim there. What is that river called today?", choices: ["the Hudson River", "the Ohio River", "the St. Lawrence River", "the Columbia River"], answer: 0, explain: "The Hudson River is named after him. The Dutch later founded New Netherland there." },
  { id: "exp-012", skill: "ss-explore", q: "Which Spanish explorer traveled through the southeastern United States and was one of the first Europeans to reach the Mississippi River?", choices: ["Francisco Coronado", "Hernando de Soto", "Samuel de Champlain", "John Cabot"], answer: 1, explain: "Hernando de Soto explored the Southeast for Spain and crossed the Mississippi River in 1541." },
  { id: "exp-013", skill: "ss-explore", q: "Which Spanish explorer searched the American Southwest for the legendary Seven Cities of Gold?", choices: ["Juan Ponce de León", "Jacques Cartier", "Francisco Coronado", "Henry Hudson"], answer: 2, explain: "Coronado searched the Southwest for cities of gold. He never found them, but he claimed the land for Spain." },
  { id: "exp-014", skill: "ss-explore", q: "Spain mostly explored and claimed land in ___.", choices: ["eastern Canada and the St. Lawrence River", "the Southeast, the Southwest, Mexico, and the Caribbean", "the Hudson River valley", "the Arctic"], answer: 1, explain: "Spanish explorers like Columbus, Ponce de León, de Soto, and Coronado claimed the Caribbean, Florida, the Southeast, and the Southwest." },
  { id: "exp-015", skill: "ss-explore", q: "In New France, French settlers and traders made much of their money from ___.", choices: ["gold mines", "tobacco plantations", "cotton farms", "the fur trade"], answer: 3, explain: "The French traded with Indigenous peoples for beaver furs, which sold for high prices in Europe." },
  { id: "exp-016", skill: "ss-explore", q: "Portuguese explorer Vasco da Gama found a sea route to ___ by sailing around the southern tip of Africa.", choices: ["Greenland", "the Mississippi River", "India", "Antarctica"], answer: 2, explain: "Da Gama reached India in 1498, giving Portugal a sea route for the spice trade." },
  { id: "exp-017", skill: "ss-explore", q: "Which was an obstacle European explorers faced?", choices: ["calm seas and accurate maps of the whole world", "disease, hunger, and fear of the unknown", "short, easy trips across the ocean", "plenty of fresh fruit on every ship"], answer: 1, explain: "Voyages were long and dangerous. Sailors faced sickness, running out of food, storms, and not knowing what lay ahead." },
  { id: "exp-018", skill: "ss-explore", q: "Which tool helped explorers find their direction at sea?", choices: ["thermometer", "compass", "rain gauge", "anemometer"], answer: 1, explain: "A compass needle points north, so sailors could tell which way they were heading even out of sight of land." },
  { id: "exp-019", skill: "ss-explore", q: "Which was an accomplishment of European exploration?", choices: ["Explorers found a short water route through North America to Asia", "Explorers proved Earth was flat", "Explorers ended all wars in Europe", "Europeans exchanged goods and ideas and improved ships and navigation tools"], answer: 3, explain: "Exploration led to new trade, better maps and ships, and claims to new lands. No explorer of that time found a water route through North America." },
  { id: "exp-020", skill: "ss-explore", q: "What was the Columbian Exchange?", choices: ["a trade route between Mali and Ghana", "a bank in Spain", "the transfer of plants, animals, people, and diseases between the Americas and Europe, Africa, and Asia after 1492", "a peace treaty between France and England"], answer: 2, explain: "After Columbus's voyages, crops, animals, people, and germs moved in both directions across the Atlantic." },
  { id: "exp-021", skill: "ss-explore", q: "Which crops traveled FROM the Americas TO Europe in the Columbian Exchange?", choices: ["horses, cattle, and pigs", "corn, potatoes, and tomatoes", "wheat, oats, and barley", "smallpox and measles"], answer: 1, explain: "Corn, potatoes, and tomatoes were first grown in the Americas. Wheat, horses, cattle, and diseases came from Europe." },
  { id: "exp-022", skill: "ss-explore", q: "Which animal, brought to the Americas by Europeans, changed how the Lakota and other Plains peoples hunted buffalo?", choices: ["the turkey", "the llama", "the bison", "the horse"], answer: 3, explain: "The Spanish brought horses. Plains peoples became skilled riders, which made hunting buffalo and traveling much faster." },
  { id: "exp-023", skill: "ss-explore", q: "After Europeans arrived, what caused the most deaths among Indigenous peoples?", choices: ["diseases such as smallpox, which their bodies had no immunity to", "earthquakes", "eating new foods like wheat", "a long drought"], answer: 0, explain: "Indigenous peoples had never been exposed to European diseases like smallpox, so these illnesses spread quickly and killed millions." },
  { id: "exp-024", skill: "ss-explore", q: "Which is an example of COOPERATION between Europeans and Indigenous peoples?", choices: ["Europeans claimed Indigenous lands for their kings", "European diseases spread through Indigenous villages", "They traded goods, and Indigenous peoples taught Europeans to grow crops like corn", "The Spanish forced Indigenous peoples to work for them"], answer: 2, explain: "Trading and sharing knowledge helped both sides. Taking land, forced labor, and disease were harms, not cooperation." },
  { id: "exp-025", skill: "ss-explore", q: "Which was a major cause of CONFLICT between Europeans and Indigenous peoples?", choices: ["They traded furs for metal tools", "Indigenous peoples taught Europeans how to plant corn", "Europeans claimed and took Indigenous lands", "Both groups shared food during hard winters"], answer: 2, explain: "Europeans claimed land that Indigenous peoples had lived on for thousands of years, which led to wars." },

  // ===== Social Studies: Citizenship and Primary Sources (ss-civics) =====
  { id: "civ-001", skill: "ss-civics", q: "What is a primary source?", choices: ["a textbook written many years later", "a first-hand record made at the time by someone who was there", "an encyclopedia article", "a movie about the past"], answer: 1, explain: "Primary sources come straight from the time and people being studied, like letters, diaries, photos, and artifacts." },
  { id: "civ-002", skill: "ss-civics", q: "Which is a PRIMARY source about early Virginia?", choices: ["a modern textbook chapter about Jamestown", "an encyclopedia article about the Powhatan", "John Smith's map of Virginia from 1612", "a documentary made in 2020"], answer: 2, explain: "John Smith drew his map at the time, from his own travels. The others were made much later by people who weren't there." },
  { id: "civ-003", skill: "ss-civics", q: "Which is a SECONDARY source?", choices: ["a diary written by a Pilgrim", "a photograph taken in 1860", "a letter written by George Washington", "a history textbook"], answer: 3, explain: "A secondary source is written later by someone who studied primary sources, like a textbook." },
  { id: "civ-004", skill: "ss-civics", q: "Your grandmother's diary from when she was in 6th grade would be a ___ source about her childhood.", choices: ["primary", "secondary", "fiction", "map"], answer: 0, explain: "She wrote it herself at the time she lived it, so it is a primary source." },
  { id: "civ-005", skill: "ss-civics", q: "An arrowhead dug up at Jamestown is an example of ___.", choices: ["a secondary source", "an artifact, a kind of primary source", "a textbook", "a biography"], answer: 1, explain: "Artifacts are objects made or used by people in the past. They are primary sources because they come from that time." },
  { id: "civ-006", skill: "ss-civics", q: "Why should historians compare several sources about the same event?", choices: ["One source is always enough", "Sources never disagree", "Different people may see the same event differently, so comparing helps find the most accurate picture", "So they can copy the longest one"], answer: 2, explain: "Each source has its own point of view. Comparing sources helps historians find what most likely happened." },
  { id: "civ-007", skill: "ss-civics", q: "Which is a trait of a good citizen?", choices: ["ignoring rules you don't like", "only caring about yourself", "spreading rumors", "respecting the rights of others"], answer: 3, explain: "Good citizens respect others, are honest, and follow rules that keep everyone safe." },
  { id: "civ-008", skill: "ss-civics", q: "You find a wallet with money in it on the playground. What would an ethical citizen do?", choices: ["keep the money and throw the wallet away", "turn it in to a teacher or the office", "leave it and tell no one", "split the money with a friend"], answer: 1, explain: "Being ethical means doing the right thing even when no one is watching, so you help it get back to its owner." },
  { id: "civ-009", skill: "ss-civics", q: "Which is an example of a responsibility of citizens?", choices: ["ignoring jury duty", "littering in parks", "obeying laws", "refusing to pay taxes"], answer: 2, explain: "Citizens have responsibilities like obeying laws, paying taxes, serving on juries, and voting when they are old enough." },
  { id: "civ-010", skill: "ss-civics", q: "What does it mean to be a global citizen?", choices: ["understanding that people around the world are connected and respecting other cultures", "only caring about your own town", "traveling to every country", "speaking every language"], answer: 0, explain: "Global citizens know their choices can affect people in other places and treat other cultures with respect." },
  { id: "civ-011", skill: "ss-civics", q: "During a class debate, a classmate disagrees with you. What shows good citizenship?", choices: ["interrupting and talking louder", "making fun of their idea", "refusing to talk to them again", "listening respectfully and answering with facts"], answer: 3, explain: "Good citizens can disagree politely. They listen, then support their own ideas with evidence." },
  { id: "civ-012", skill: "ss-civics", q: "A letter by an English colonist about a fight with the Powhatan might tell only the colonist's side of the story. This is an example of ___.", choices: ["a secondary source", "point of view (bias)", "an artifact", "a time line"], answer: 1, explain: "Every author has a point of view. Historians look for other sources, like Powhatan oral histories, to get the whole story." },

  // ===== Social Studies: Colonial America (ss-colonial) =====
  { id: "col-001", skill: "ss-colonial", q: "Why is the English colony at Roanoke (1587) called the 'Lost Colony'?", choices: ["It was the first Spanish colony", "The colonists disappeared, and no one knows for sure what happened to them", "It was later renamed New York", "The Pilgrims lost their way going there"], answer: 1, explain: "When supply ships returned in 1590, the colonists were gone. The only clue was the word 'CROATOAN' carved on a post." },
  { id: "col-002", skill: "ss-colonial", q: "Roanoke Island, site of England's 'Lost Colony,' is in present-day ___.", choices: ["Massachusetts", "New York", "Georgia", "North Carolina"], answer: 3, explain: "Roanoke Island is off the coast of present-day North Carolina." },
  { id: "col-003", skill: "ss-colonial", q: "Jamestown, founded in 1607, was the first ___.", choices: ["Spanish mission in North America", "French fur-trading post", "colony founded by the Pilgrims", "permanent English settlement in North America"], answer: 3, explain: "Jamestown, Virginia was the first English settlement in North America that lasted." },
  { id: "col-004", skill: "ss-colonial", q: "Jamestown was paid for by the Virginia Company of London. Why did the company's investors pay for it?", choices: ["They hoped to make money (economic reasons)", "They wanted religious freedom for the Puritans", "They wanted to start a colony for Catholics", "They wanted to explore Antarctica"], answer: 0, explain: "The Virginia Company was a business. Its investors hoped to make a profit, at first by finding gold." },
  { id: "col-005", skill: "ss-colonial", q: "Which problems did the early Jamestown settlers face?", choices: ["a dry desert with no water", "freezing Arctic temperatures all year", "no Indigenous neighbors at all", "hunger, disease from swampy land and bad water, and conflict"], answer: 3, explain: "Jamestown was built on swampy land with unhealthy water. Many settlers died of disease and hunger, especially during the 'Starving Time.'" },
  { id: "col-006", skill: "ss-colonial", q: "How did John Smith help Jamestown survive?", choices: ["He planted the first tobacco crop", "He wrote the Mayflower Compact", "He made the rule 'he who does not work, shall not eat' and traded with the Powhatan for food", "He founded Plymouth"], answer: 2, explain: "Smith made the settlers work instead of searching for gold, and he traded with the Powhatan for corn." },
  { id: "col-007", skill: "ss-colonial", q: "Who introduced a new kind of tobacco that became Virginia's cash crop and helped the colony make money?", choices: ["John Smith", "John Rolfe", "William Bradford", "Christopher Newport"], answer: 1, explain: "John Rolfe grew a sweeter tobacco that sold well in England, which turned Jamestown into a money-making colony." },
  { id: "col-008", skill: "ss-colonial", q: "Tobacco became Virginia's cash crop. What is a cash crop?", choices: ["a crop grown mainly to sell for profit", "a crop grown only to feed your own family", "a crop that grows without water", "a crop traded only with the Powhatan"], answer: 0, explain: "A cash crop is grown to be sold. Tobacco was shipped to England and sold for money." },
  { id: "col-009", skill: "ss-colonial", q: "In 1619, the House of Burgesses first met in Jamestown. Why was it important?", choices: ["It was the first English fort in Africa", "It was the king's palace in London", "It was the first representative legislature (elected lawmaking group) in the American colonies", "It was the first town meeting in New England"], answer: 2, explain: "The House of Burgesses was the start of representative government in America: colonists elected people to make laws for them." },
  { id: "col-010", skill: "ss-colonial", q: "Which two important events happened in Virginia in 1619?", choices: ["Jamestown was founded and the Pilgrims arrived", "the House of Burgesses first met and the first enslaved Africans were brought to Virginia", "the Mayflower Compact was signed and Roanoke was founded", "Columbus landed and Quebec was founded"], answer: 1, explain: "In 1619 the House of Burgesses met for the first time, and Africans who had been captured and enslaved were brought to Point Comfort, near Jamestown." },
  { id: "col-011", skill: "ss-colonial", q: "The Pilgrims sailed to America on the Mayflower in 1620 mainly to ___.", choices: ["find gold", "grow tobacco", "trade furs with France", "practice their religion freely"], answer: 3, explain: "The Pilgrims had separated from the Church of England and wanted a place where they could worship their own way." },
  { id: "col-012", skill: "ss-colonial", q: "The Pilgrims founded Plymouth Colony in present-day ___.", choices: ["Virginia", "Pennsylvania", "Massachusetts", "Georgia"], answer: 2, explain: "Plymouth was in present-day Massachusetts, in New England." },
  { id: "col-013", skill: "ss-colonial", q: "Why was the Mayflower Compact important?", choices: ["It ended slavery in the colonies", "It was an early example of self-government: the men agreed to make and obey fair laws for the colony", "It was a peace treaty with Spain", "It created the House of Burgesses"], answer: 1, explain: "Before landing, the men aboard the Mayflower agreed to govern themselves and follow laws made for the good of the colony." },
  { id: "col-014", skill: "ss-colonial", q: "Which Indigenous people helped the Pilgrims survive by teaching them to plant corn and fish?", choices: ["the Lakota", "the Inuit", "the Pueblo", "the Wampanoag"], answer: 3, explain: "The Wampanoag, and Tisquantum (Squanto), a Patuxet man living among them, helped the Pilgrims learn to farm and fish in New England." },
  { id: "col-015", skill: "ss-colonial", q: "The Puritans founded the Massachusetts Bay Colony because they wanted to ___.", choices: ["grow tobacco for profit", "live by their own religious beliefs", "find the Seven Cities of Gold", "start a French fur-trading post"], answer: 1, explain: "The Puritans wanted to 'purify' the Church of England and build a community based on their religious beliefs." },
  { id: "col-016", skill: "ss-colonial", q: "Puritan leaders forced Roger Williams to leave Massachusetts because of his religious views. What did he do next?", choices: ["He founded Rhode Island, where people had more religious freedom", "He sailed back to England and never returned", "He founded Jamestown", "He became governor of Virginia"], answer: 0, explain: "Roger Williams founded Rhode Island as a place where people could worship as they chose." },
  { id: "col-017", skill: "ss-colonial", q: "The New England colonies had rocky soil, a short growing season, thick forests, and good harbors. Which jobs were common there?", choices: ["working on large tobacco plantations", "fishing, shipbuilding, and trade", "growing rice in flooded fields", "mining gold in the mountains"], answer: 1, explain: "Poor soil made big farms hard, but forests gave wood for ships and the ocean gave fish and trade." },
  { id: "col-018", skill: "ss-colonial", q: "The Mid-Atlantic colonies were called the 'breadbasket colonies' because ___.", choices: ["they imported all their bread from England", "they only grew tobacco", "they had no farms at all", "they grew large amounts of wheat and other grains"], answer: 3, explain: "Fertile soil and a moderate climate let Mid-Atlantic farmers grow lots of grain to make bread." },
  { id: "col-019", skill: "ss-colonial", q: "The Southern colonies had fertile soil, a long growing season, and many rivers. This led to ___.", choices: ["fishing and shipbuilding as the main jobs", "small farms on rocky soil", "large plantations growing cash crops like tobacco and rice", "an economy based only on the fur trade"], answer: 2, explain: "Warm weather and rich soil were perfect for big plantations that grew cash crops to sell." },
  { id: "col-020", skill: "ss-colonial", q: "Which colony did William Penn found as a place where Quakers and people of other faiths could worship freely?", choices: ["Pennsylvania", "Georgia", "Virginia", "Massachusetts"], answer: 0, explain: "Pennsylvania means 'Penn's woods.' Penn welcomed people of many religions." },
  { id: "col-021", skill: "ss-colonial", q: "The Mid-Atlantic colonies were known for ___.", choices: ["only Puritans, who required everyone to follow one church", "people of many different religions and backgrounds living there", "only members of the Church of England", "having no cities or ports"], answer: 1, explain: "The Mid-Atlantic colonies, like New York and Pennsylvania, had a diverse mix of people and religions, plus busy ports like Philadelphia." },
  { id: "col-022", skill: "ss-colonial", q: "In Southern colonies like Virginia, the official church was the ___.", choices: ["Puritan church", "Quaker meeting", "Catholic Church", "Church of England (Anglican Church)"], answer: 3, explain: "Virginia's official church was the Church of England, and colonists were expected to support it." },
  { id: "col-023", skill: "ss-colonial", q: "In the New England colonies, people made decisions about their towns in ___.", choices: ["the House of Burgesses", "the king's court only", "town meetings", "plantation owners' meetings only"], answer: 2, explain: "New England colonists gathered at town meetings to discuss and vote on local issues." },
  { id: "col-024", skill: "ss-colonial", q: "Many colonists came to America as indentured servants. What was an indentured servant?", choices: ["a person enslaved for life", "a person who agreed to work for several years in exchange for the trip to America", "the governor of a colony", "a sailor in the Spanish navy"], answer: 1, explain: "Indentured servants worked for a set number of years, often four to seven, to pay for their voyage. Then they were free." },
  { id: "col-025", skill: "ss-colonial", q: "How was the life of an enslaved African different from that of an indentured servant?", choices: ["Enslaved people worked for only a few years", "Enslaved people chose to come to America", "Enslaved people were held in bondage for life, and their children were also enslaved", "There was no difference"], answer: 2, explain: "Indentured servants became free after their contract ended. Under colonial laws, enslaved people were never freed by time, and slavery was passed down to their children." },
  { id: "col-026", skill: "ss-colonial", q: "The triangular trade connected which three areas?", choices: ["Asia, Australia, and Antarctica", "Ghana, Mali, and Songhai", "England, France, and Spain", "Europe, Africa, and the Americas"], answer: 3, explain: "Ships carried goods from Europe to Africa, enslaved Africans to the Americas, and raw materials like sugar and tobacco back to Europe." },
  { id: "col-027", skill: "ss-colonial", q: "The part of the triangular trade in which enslaved Africans were forced across the Atlantic Ocean on crowded, dangerous ships was called the ___.", choices: ["Northwest Passage", "Middle Passage", "Silk Road", "Oregon Trail"], answer: 1, explain: "The Middle Passage was the cruel voyage from Africa to the Americas. Many people died from disease and terrible conditions." },
  { id: "col-028", skill: "ss-colonial", q: "Why did slavery grow most in the Southern colonies?", choices: ["The South had rocky soil and a short growing season", "Southern colonies made most of their money from fishing", "Large plantations growing tobacco and rice needed many workers, and plantation owners used enslaved people to do the work", "The Southern colonies had no farms"], answer: 2, explain: "Slavery existed in all the colonies, but the South's big plantations depended on the forced labor of enslaved people." },
  { id: "col-029", skill: "ss-colonial", q: "Relations between the Jamestown colonists and the Powhatan ___.", choices: ["were always peaceful", "included trade and cooperation, but also wars over land", "never happened because the Powhatan lived far away", "were controlled by France"], answer: 1, explain: "The Powhatan traded food with the colonists, but as the English took more land, the two sides fought several wars." },
  { id: "col-030", skill: "ss-colonial", q: "Pocahontas, the daughter of the Powhatan leader, married ___, which helped bring a period of peace.", choices: ["John Smith", "William Bradford", "Christopher Columbus", "John Rolfe"], answer: 3, explain: "Pocahontas married John Rolfe in 1614. Many people think she married John Smith, but that is a myth." },
];
